# Homebrew's Linux prefix must exist and be writable before `brew` runs.
systemd.tmpfiles.rules = [
  "d /home/linuxbrew 0755 ${username} users -"
  "d /home/linuxbrew/.linuxbrew 0755 ${username} users -"
];

# Bootstrap Homebrew itself, as the owning user, once the prefix exists.
systemd.services.linuxbrew-install = {
  description = "Install Homebrew into /home/linuxbrew/.linuxbrew";
  wantedBy = [ "multi-user.target" ];
  wants = [ "network-online.target" ];
  after = [
    "network-online.target"
    "systemd-tmpfiles-setup.service"
  ];
  serviceConfig = {
    Type = "oneshot";
    RemainAfterExit = true;
    User = username;
    Group = "users";
    Environment = [
      "HOME=/home/${username}"
      "GIT_SSL_CAINFO=/etc/ssl/certs/ca-certificates.crt"
      "SSL_CERT_FILE=/etc/ssl/certs/ca-certificates.crt"
    ];
    ExecStart = "${pkgs.bash}/bin/bash ${./linuxbrew-install.sh} /home/linuxbrew/.linuxbrew ${pkgs.git}/bin/git";
  };
};
